import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './App.css';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';

function App() {
  const [activeTab, setActiveTab] = useState('chat');
  const [messages, setMessages] = useState([]);
  const [chatHistory, setChatHistory] = useState([]);
  const [activeChat, setActiveChat] = useState(null);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [tools, setTools] = useState([]);
  const [workspaceConfig, setWorkspaceConfig] = useState(null);
  const [llmInfo, setLlmInfo] = useState(null);
  const [connected, setConnected] = useState(false);
  const [analysisResult, setAnalysisResult] = useState(null);
  const [refactorCode, setRefactorCode] = useState('');
  const [refactorInstructions, setRefactorInstructions] = useState('');
  const [completions, setCompletions] = useState([]);
  const [agentRunning, setAgentRunning] = useState(false);
  const [agentLogs, setAgentLogs] = useState([]);
  const [settings, setSettings] = useState({
    llmUrl: 'http://localhost:11434',
    llmModel: 'llama3.2',
    maxTokens: 4096,
    temperature: 0.7,
    autoComplete: false
  });
  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);

  useEffect(() => {
    loadHealthInfo();
    loadTools();
    loadChatHistory();
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const loadHealthInfo = async () => {
    try {
      const response = await axios.get(`${API_URL}/health`, { timeout: 3000 });
      setWorkspaceConfig(response.data.workspace);
      setLlmInfo(response.data.llm);
      setConnected(response.data.llm?.available || false);
    } catch (error) {
      setConnected(false);
    }
  };

  const loadTools = async () => {
    try {
      const response = await axios.get(`${API_URL}/tools`);
      setTools(response.data);
    } catch (error) {
      console.error('Error loading tools:', error);
    }
  };

  const loadChatHistory = () => {
    const history = localStorage.getItem('chatHistory');
    if (history) {
      setChatHistory(JSON.parse(history));
    }
  };

  const saveChatHistory = (newHistory) => {
    localStorage.setItem('chatHistory', JSON.stringify(newHistory));
    setChatHistory(newHistory);
  };

  const startNewChat = () => {
    const newChat = {
      id: Date.now(),
      title: 'New Chat',
      messages: [],
      timestamp: new Date().toISOString()
    };
    const updated = [newChat, ...chatHistory];
    saveChatHistory(updated);
    setActiveChat(newChat.id);
    setMessages([]);
  };

  const selectChat = (chatId) => {
    const chat = chatHistory.find(c => c.id === chatId);
    if (chat) {
      setActiveChat(chatId);
      setMessages(chat.messages || []);
    }
  };

  const sendMessage = async () => {
    if (!inputValue.trim() || isLoading) return;

    const userMessage = {
      role: 'user',
      content: inputValue,
      timestamp: new Date().toISOString()
    };

    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    setInputValue('');
    setIsLoading(true);

    const currentChatId = activeChat || Date.now();
    if (!activeChat) {
      setActiveChat(currentChatId);
      const newChat = {
        id: currentChatId,
        title: inputValue.slice(0, 30) + (inputValue.length > 30 ? '...' : ''),
        messages: newMessages,
        timestamp: new Date().toISOString()
      };
      const updated = [newChat, ...chatHistory];
      saveChatHistory(updated);
    } else {
      const updated = chatHistory.map(c => 
        c.id === activeChat 
          ? { ...c, messages: newMessages, timestamp: new Date().toISOString() }
          : c
      );
      saveChatHistory(updated);
    }

    try {
      const response = await axios.post(`${API_URL}/chat`, {
        messages: [userMessage]
      });

      const assistantMessage = {
        role: 'assistant',
        content: response.data.response,
        timestamp: new Date().toISOString()
      };

      const finalMessages = [...newMessages, assistantMessage];
      setMessages(finalMessages);

      const updatedHistory = chatHistory.map(c => 
        c.id === currentChatId 
          ? { ...c, messages: finalMessages, timestamp: new Date().toISOString() }
          : c
      );
      saveChatHistory(updatedHistory);
    } catch (error) {
      const errorMessage = {
        role: 'assistant',
        content: 'Error: Could not process your request. Please check the server.',
        timestamp: new Date().toISOString()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
      inputRef.current?.focus();
    }
  };

  const runAnalysis = async () => {
    setIsLoading(true);
    try {
      const response = await axios.post(`${API_URL}/analyze`, {});
      setAnalysisResult(response.data);
    } catch (error) {
      setAnalysisResult({ summary: 'Error analyzing code', issues: error.message });
    } finally {
      setIsLoading(false);
    }
  };

  const runRefactor = async () => {
    if (!refactorCode.trim()) {
      alert('Enter code to refactor');
      return;
    }
    setIsLoading(true);
    try {
      const response = await axios.post(`${API_URL}/refactor`, {
        code: refactorCode,
        instructions: refactorInstructions
      });
      setAnalysisResult({ refactored: response.data.refactored });
    } catch (error) {
      setAnalysisResult({ refactored: 'Error: ' + error.message });
    } finally {
      setIsLoading(false);
    }
  };

  const getCompletions = async () => {
    setIsLoading(true);
    try {
      const response = await axios.post(`${API_URL}/completion`, {});
      setCompletions(response.data.suggestions || []);
    } catch (error) {
      setCompletions(['Error getting completions']);
    } finally {
      setIsLoading(false);
    }
  };

  const startAgent = async () => {
    setIsLoading(true);
    try {
      await axios.post(`${API_URL}/agent/start`, {});
      setAgentRunning(true);
      addAgentLog('Agent started');
    } catch (error) {
      addAgentLog('Error: ' + error.message);
    } finally {
      setIsLoading(false);
    }
  };

  const stopAgent = async () => {
    setIsLoading(true);
    try {
      await axios.post(`${API_URL}/agent/stop`, {});
      setAgentRunning(false);
      addAgentLog('Agent stopped');
    } catch (error) {
      addAgentLog('Error: ' + error.message);
    } finally {
      setIsLoading(false);
    }
  };

  const addAgentLog = (message) => {
    const timestamp = new Date().toLocaleTimeString();
    setAgentLogs(prev => [...prev, { timestamp, message }]);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  const handleQuickAction = (action) => {
    setInputValue(action);
    sendMessage();
  };

  const handleRefactorTemplate = (template) => {
    const templates = {
      'extract': 'استخراج هذا الكود إلى دالة منفصلة',
      'rename': 'إعادة تسمية المتغيرات والدوال',
      'inline': 'دمج المتغير المباشر',
      'optimize': 'تحسين الأداء وإزالة الكود المكر',
      'clean': 'تنظيف الكود وإزالة الأسطر غير المستخدمة'
    };
    setRefactorInstructions(templates[template] || '');
  };

  const formatTime = (timestamp) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diff = now - date;

    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    if (diff < 86400000) return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    return date.toLocaleDateString();
  };

  const renderMessageContent = (content) => {
    const codeBlockRegex = /```(\w+)?\n([\s\S]*?)```/g;
    const parts = content.split(codeBlockRegex);

    return parts.map((part, i) => {
      if (i % 3 === 0 && part) {
        return <p key={i}>{part}</p>;
      }
      if (i % 3 === 2) {
        const lang = parts[i - 1] || 'code';
        return (
          <div key={i} className="code-block">
            <div className="code-block-header">
              <span>{lang}</span>
            </div>
            <pre><code>{part}</code></pre>
          </div>
        );
      }
      return null;
    });
  };

  const tabs = [
    { id: 'chat', label: '💬 محادثة', icon: '💬' },
    { id: 'analyze', label: '🔍 تحليل', icon: '🔍' },
    { id: 'refactor', label: '🔧 إعادة هيكلة', icon: '🔧' },
    { id: 'completion', label: '✨ إكمال', icon: '✨' },
    { id: 'agent', label: '⚡ الوكيل', icon: '⚡' },
    { id: 'settings', label: '⚙️ الإعدادات', icon: '⚙️' },
  ];

  return (
    <div className="app-container">
      {/* Header */}
      <header className="app-header">
        <h1>
          <div className="header-logo">🤖</div>
          أدوات الذكاء الاصطناعي المصغرة
        </h1>
      </header>

      {/* Navigation Tabs */}
      <nav className="nav-tabs">
        {tabs.map(tab => (
          <button
            key={tab.id}
            className={`nav-tab ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </nav>

      {/* Config Info */}
      <div className="config-info">
        <span><strong>المساحة العمل:</strong> {workspaceConfig?.workspace_path || 'غير مكون'}</span>
        <span><strong>نموذج الذكاء:</strong> {llmInfo?.provider || 'N/A'}/{llmInfo?.model || 'N/A'}</span>
        <span><strong>الأدوات:</strong> {tools.length} متوفر</span>
      </div>

      {/* Main Content */}
      <div className="main-content">
        {/* Sidebar */}
        <aside className="sidebar">
          <div className="sidebar-header">
            <h2>Chat History</h2>
            <div className="sidebar-actions">
              <button className="sidebar-btn" onClick={startNewChat}>+ New</button>
            </div>
          </div>
          <div className="chat-history">
            {chatHistory.length === 0 ? (
              <div className="empty-state">No chats yet</div>
            ) : (
              chatHistory.map(chat => (
                <div 
                  key={chat.id} 
                  className={`chat-history-item ${activeChat === chat.id ? 'active' : ''}`}
                  onClick={() => selectChat(chat.id)}
                >
                  <div className="chat-history-item-title">{chat.title}</div>
                  <div className="chat-history-item-time">{formatTime(chat.timestamp)}</div>
                </div>
              ))
            )}
          </div>
        </aside>

        {/* Panel Content */}
        <main className="chat-panel">
          {/* Chat View */}
          {activeTab === 'chat' && (
            <>
              <div className="quick-actions">
                <div className="quick-action" onClick={() => handleQuickAction('Explain this code')}>📖 erklären</div>
                <div className="quick-action" onClick={() => handleQuickAction('Find bugs')}>🐛 Bugs finden</div>
                <div className="quick-action" onClick={() => handleQuickAction('Optimize this code')}>⚡ تحسين</div>
                <div className="quick-action" onClick={() => handleQuickAction('Add comments')}>💬 تعليق</div>
              </div>
              <div className="chat-messages">
                {messages.length === 0 && !isLoading && (
                  <div className="empty-state">
                    <div className="empty-state-icon">💬</div>
                    ابدأ محادثة...
                  </div>
                )}
                {messages.map((message, index) => (
                  <div key={index} className={`message ${message.role}`}>
                    <div className="message-header">
                      <div className="avatar">{message.role === 'user' ? 'أ' : 'ذ'}</div>
                      <span className="name">{message.role === 'user' ? 'أنت' : 'الذكاء الاصطناعي'}</span>
                    </div>
                    <div className="message-content">
                      {renderMessageContent(message.content)}
                    </div>
                  </div>
                ))}
                {isLoading && (
                  <div className="message assistant">
                    <div className="message-header">
                      <div className="avatar">ذ</div>
                      <span className="name">الذكاء الاصطناعي</span>
                    </div>
                    <div className="message-content">
                      <div className="loading"><div className="loading-spinner"></div>جاري التفكير...</div>
                    </div>
                  </div>
                )}
                <div ref={messagesEndRef} />
              </div>
              <div className="input-area">
                <div className="input-wrapper">
                  <textarea
                    ref={inputRef}
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                    onKeyPress={handleKeyPress}
                    placeholder="اكتب رسالتك... (Enter للإرسال)"
                  />
                  <button className="send-btn" onClick={sendMessage} disabled={isLoading || !inputValue.trim()}>
                    {isLoading ? '...' : 'إرسال'}
                  </button>
                </div>
              </div>
            </>
          )}

          {/* Analyze View */}
          {activeTab === 'analyze' && (
            <div className="analysis-view">
              {analysisResult ? (
                <>
                  {analysisResult.summary && (
                    <div className="analysis-section">
                      <h3>Summary</h3>
                      <p>{analysisResult.summary}</p>
                    </div>
                  )}
                  {analysisResult.issues && (
                    <div className="analysis-section">
                      <h3>المشاكل</h3>
                      <p>{analysisResult.issues}</p>
                    </div>
                  )}
                  {analysisResult.suggestions && (
                    <div className="analysis-section">
                      <h3>الاقتراحات</h3>
                      <p>{analysisResult.suggestions}</p>
                    </div>
                  )}
                </>
              ) : (
                <div className="empty-state">
                  <div className="empty-state-icon">🔍</div>
                  انقر على "تشغيل التحليل" لتحليل الكود
                </div>
              )}
              <button className="action-btn" onClick={runAnalysis} disabled={isLoading}>
                {isLoading ? 'جاري التحليل...' : 'تشغيل التحليل'}
              </button>
            </div>
          )}

          {/* Refactor View */}
          {activeTab === 'refactor' && (
            <div className="refactor-view">
              <div className="refactor-templates">
                <div className="refactor-template" onClick={() => handleRefactorTemplate('extract')}>📤 استخراج دالة</div>
                <div className="refactor-template" onClick={() => handleRefactorTemplate('rename')}>✏️ إعادة تسمية</div>
                <div className="refactor-template" onClick={() => handleRefactorTemplate('inline')}>📥 دمج في place</div>
                <div className="refactor-template" onClick={() => handleRefactorTemplate('optimize')}>⚡ تحسين الأداء</div>
                <div className="refactor-template" onClick={() => handleRefactorTemplate('clean')}>🧹 تنظيف الكود</div>
              </div>
              <div className="refactor-original">
                <label>الكود الأصلي:</label>
                <textarea
                  value={refactorCode}
                  onChange={(e) => setRefactorCode(e.target.value)}
                  placeholder="أدخل الكود المراد إعادة هيكلته..."
                />
              </div>
              <div className="refactor-instructions">
                <label>التعليمات:</label>
                <textarea
                  value={refactorInstructions}
                  onChange={(e) => setRefactorInstructions(e.target.value)}
                  placeholder="صف كيف تريد إعادة هيكلة الكود..."
                />
              </div>
              {analysisResult?.refactored && (
                <div className="analysis-section">
                  <h3>النتيجة المعاد هيكلتها:</h3>
                  <pre><code>{analysisResult.refactored}</code></pre>
                </div>
              )}
              <button className="action-btn" onClick={runRefactor} disabled={isLoading}>
                {isLoading ? 'جاري إعادة الهيكلة...' : 'إعادة هيكلة الكود'}
              </button>
            </div>
          )}

          {/* Completion View */}
          {activeTab === 'completion' && (
            <div className="completion-view">
              <button className="action-btn" onClick={getCompletions} disabled={isLoading}>
                {isLoading ? 'جاري الحصول على الإكمالات...' : 'الحصول على الإكمالات'}
              </button>
              <div className="completion-suggestions">
                {completions.map((completion, i) => (
                  <div key={i} className="completion-item">
                    <code>{completion}</code>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Agent View */}
          {activeTab === 'agent' && (
            <div className="agent-view">
              <div className="agent-status-card">
                <h3>حالة الوكيل</h3>
                <div className="agent-status-indicator">
                  <span className="status-dot" style={{ background: agentRunning ? 'var(--status-connected)' : 'var(--status-disconnected)' }}></span>
                  <span>{agentRunning ? 'قيد التشغيل' : 'متوقف'}</span>
                </div>
              </div>
              <div className="agent-actions">
                <button className="action-btn" onClick={startAgent} disabled={isLoading || agentRunning}>
                  {isLoading ? 'جاري التشغيل...' : 'تشغيل الوكيل'}
                </button>
                <button className="action-btn secondary" onClick={stopAgent} disabled={isLoading || !agentRunning}>
                  {isLoading ? 'جاري الإيقاف...' : 'إيقاف الوكيل'}
                </button>
              </div>
              <div className="agent-info">
                <div className="agent-info-item">
                  <label>مساحة العمل:</label>
                  <span>{workspaceConfig?.workspace_path || 'غير مكون'}</span>
                </div>
                <div className="agent-info-item">
                  <label>نموذج الذكاء:</label>
                  <span>{llmInfo?.provider || 'N/A'}/{llmInfo?.model || 'N/A'}</span>
                </div>
              </div>
              <div className="agent-logs">
                {agentLogs.length === 0 ? (
                  <div style={{ padding: '16px', color: 'var(--text-secondary)', textAlign: 'center' }}>
                    ستظهر سجلات الوكيل هنا
                  </div>
                ) : (
                  agentLogs.map((log, i) => (
                    <div key={i} className="agent-log-item">
                      <span className="log-timestamp">[{log.timestamp}]</span> {log.message}
                    </div>
                  ))
                )}
              </div>
            </div>
          )}

          {/* Settings View */}
          {activeTab === 'settings' && (
            <div className="settings-view">
              <div className="settings-section">
                <h3>⚙️ إعدادات الذكاء الاصطناعي</h3>
                <div className="settings-group">
                  <label>رابط خادم الذكاء الاصطناعي:</label>
                  <input 
                    type="text" 
                    value={settings.llmUrl}
                    onChange={(e) => setSettings({...settings, llmUrl: e.target.value})}
                    placeholder="http://localhost:11434" 
                  />
                </div>
                <div className="settings-group">
                  <label>النموذج:</label>
                  <select 
                    value={settings.llmModel}
                    onChange={(e) => setSettings({...settings, llmModel: e.target.value})}
                  >
                    <option value="llama3.2">Llama 3.2</option>
                    <option value="codellama">CodeLlama</option>
                    <option value="mistral">Mistral</option>
                    <option value="mixtral">Mixtral</option>
                  </select>
                </div>
              </div>
              <div className="settings-section">
                <h3>⚡ إعدادات الوكيل</h3>
                <div className="settings-group">
                  <label>الحد الأقصى للتوكنات:</label>
                  <input 
                    type="number" 
                    value={settings.maxTokens}
                    onChange={(e) => setSettings({...settings, maxTokens: parseInt(e.target.value)})}
                    min="512" 
                    max="8192" 
                  />
                </div>
                <div className="settings-group">
                  <label>درجة الحرارة: {settings.temperature}</label>
                  <input 
                    type="range" 
                    min="0" 
                    max="1" 
                    step="0.1" 
                    value={settings.temperature}
                    onChange={(e) => setSettings({...settings, temperature: parseFloat(e.target.value)})}
                  />
                </div>
                <div className="settings-group">
                  <label className="checkbox-label">
                    <input 
                      type="checkbox" 
                      checked={settings.autoComplete}
                      onChange={(e) => setSettings({...settings, autoComplete: e.target.checked})}
                    />
                    الإكمال التلقائي للكود
                  </label>
                </div>
              </div>
              <div className="settings-section">
                <h3>⌨️ مفاتيح الاختصار</h3>
                <div className="shortcuts-list">
                  <div className="shortcut-item"><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>C</kbd> <span>فتح المحادثة</span></div>
                  <div className="shortcut-item"><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>A</kbd> <span>تحليل الكود</span></div>
                  <div className="shortcut-item"><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> <span>إعادة الهيكلة</span></div>
                </div>
              </div>
              <button className="action-btn" onClick={() => alert('تم حفظ الإعدادات!')}>
                حفظ الإعدادات
              </button>
            </div>
          )}
        </main>
      </div>

      {/* Status Bar */}
      <footer className="status-bar">
        <div className={`status-bar-item ${connected ? 'connected' : 'disconnected'}`}>
          <span className="status-dot"></span>
          {connected ? 'متصل' : 'غير متصل'}
        </div>
        <div className="status-bar-item">{llmInfo?.provider || 'N/A'}:{llmInfo?.model || 'N/A'}</div>
        <div className="status-bar-item">{workspaceConfig?.workspace_path || 'لا توجد مساحة عمل'}</div>
        <div className="status-bar-item" style={{ marginLeft: 'auto' }}>{chatHistory.length} محادثات</div>
      </footer>
    </div>
  );
}

export default App;
